#!/bin/bash
# LOCAL ONLY — extracts private voice studio into the PersonalityProtect checkout.
# Public checkout pack: Contoso templates only — no personal seed posts.
set -euo pipefail
cd "${1:-$HOME/Projects/personality-protect}"
mkdir -p private
python3 <<'PY'
import base64, tarfile, io
from pathlib import Path
b64 = r''''''
raw = base64.b64decode(b64)
with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tar:
    tar.extractall(path=".")
print("ok:", Path("private/studio.py").resolve())
print("prompts:", sorted(p.name for p in Path("private/prompts").glob("*.md")))
li = list(Path("private/seeds/linkedin").glob("*.md"))
ar = list(Path("private/seeds/articles").glob("*.md"))
print("seeds linkedin:", len(li))
print("seeds articles:", len(ar))
PY
if [ ! -f private/.env ] && [ -f private/.env.example ]; then
  cp private/.env.example private/.env
  echo "Wrote private/.env from example — add API keys if missing."
fi
echo
echo "Next (seeds already present):  python3 private/studio.py --skip-seeds"
echo "Next (no seeds yet):           python3 private/studio.py --collect-seeds"
